-            decl.declarations
-                .iter()
-                .map(|d| self.convert_variable_declarator(d, kind)),
-        );
-        let declare = decl.declare.unwrap_or(false);
-        self.builder
-            .variable_declaration(SPAN, kind, declarators, declare)
