-/// Map OXC ScopeFlags to our ScopeKind.
-fn get_scope_kind(
-    flags: oxc_syntax::scope::ScopeFlags,
-    semantic: &Semantic,
-    scope_id: oxc_syntax::scope::ScopeId,
