-/// Find the binding identifier's start position within an AST node.
-fn find_binding_identifier_start(kind: AstKind, name: &str) -> Option<u32> {
-    match kind {
-        AstKind::BindingIdentifier(ident) => {
-            if ident.name.as_str() == name {
