-                None
-            }
-        }
-        AstKind::VariableDeclarator(decl) => find_identifier_in_pattern(&decl.id, name),
-        AstKind::Function(func) => func.id.as_ref().and_then(|id| {
-            if id.name.as_str() == name {
-                Some(id.span.start)
-            } else {
-                None
-            }
-        }),
-        AstKind::Class(class) => class.id.as_ref().and_then(|id| {
-            if id.name.as_str() == name {
