-        bindings: collector.bindings,
-        node_to_scope: collector.node_to_scope,
-        node_to_scope_end: collector.node_to_scope_end,
-        reference_to_binding: indexmap::IndexMap::new(),
-        ref_node_id_to_binding,
-        node_id_to_scope,
